#pragma config(Motor,  port3,        pressArmServoA, tmotorServoStandard, openLoop)
#pragma config(Motor,  port4,        pressArmServoB, tmotorServoStandard, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
  Servo centering for the press arm (two servos, motor ports 3 and 4).

  Sends both servos to the center (0) and holds them there until you press Stop
  or switch the robot off. Use it to (re)attach the arm with both servos centered.

  How to use:
    1. Take the arm (or its shaft) OFF both servos first, so the servos can turn
       freely. Do not run this with the arm still attached if the two servos might
       be out of line with each other: they would fight.
    2. Download and press Start. Both servo outputs turn to the center and stay there.
    3. While the program is running, slide the arm back on at the middle angle,
       halfway between "arm up" and "pressing the button".
    4. Press Stop, then run servo_angle_test.c to find the up and press values.
*/

task main()
{
    motor[pressArmServoA] = 0;
    motor[pressArmServoB] = 0;

    while(true)
        wait1Msec(100);
}
